let b = 0;

function setup() {
  createCanvas(900, 400);
  background(255);
  fill(255, 15);
  noSmooth();
}

function draw() {
  noStroke();  
  rect(0, 0, width, height);

  stroke(0);  
  for (let x = 0; x < width; x += 8) {
    for (let y = 0; y < height; y += 8) {
      let a = 4 * noise(x / 300.0, y / 300.0) * TWO_PI + b;
      point(x + 100 * cos(a), y + 100 * sin(a));
    }
  }

  b += 0.01;
}
